//! Convert instructions generated by older Cliora versions to device-independent prompt text.
use super::reference;
use uuid::Uuid;

fn legacy_command(line: &str) -> Option<String> {
    let (program, args) = line
        .trim()
        .split_once(" --cliora-internal-secret-cli-v1 --installation ")?;
    let program = program.strip_prefix("& ").unwrap_or(program);
    let path = if let Some(quoted) = program
        .strip_prefix('\'')
        .and_then(|p| p.strip_suffix('\''))
    {
        // The generator escapes a quote as '' (PowerShell) or '\'' (POSIX).
        if quoted.replace("'\\''", "").replace("''", "").contains('\'') {
            return None;
        }
        quoted
    } else {
        if !program
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || b"._/:=@+-".contains(&c))
        {
            return None;
        }
        program
    };
    let basename = path.rsplit(['/', '\\']).next()?;
    if !basename.eq_ignore_ascii_case("cliora.exe") && !basename.eq_ignore_ascii_case("cliora") {
        return None;
    }
    if !path.starts_with('/') && !path.starts_with("\\\\") && path.as_bytes().get(1) != Some(&b':')
    {
        return None;
    }
    let args = args.strip_suffix(" | Out-String -Stream").unwrap_or(args);
    let mut words = args.split_ascii_whitespace();
    Uuid::parse_str(words.next()?).ok()?;
    match words.collect::<Vec<_>>().as_slice() {
        ["list"] => Some("list_secrets".into()),
        ["read", "--secret", id] => Some(reference::format(&Uuid::parse_str(id).ok()?.to_string())),
        ["use", "--secret", id, "--executor", executor] => {
            Uuid::parse_str(executor).ok()?;
            Some(reference::format(&Uuid::parse_str(id).ok()?.to_string()))
        }
        _ => None,
    }
}

pub fn prompt_body(body: &str) -> std::borrow::Cow<'_, str> {
    if !body.contains(" --cliora-internal-secret-cli-v1 --installation ") {
        return body.into();
    }
    let lines: Vec<_> = body.split_inclusive('\n').collect();
    let mut output = String::with_capacity(body.len());
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i].trim_end_matches(['\r', '\n']);
        let rest = &lines[i + 1..];
        // The two metadata lines immediately following the old template title
        // contained the originating installation label, UUID and executable path.
        if matches!(
            line,
            "## 栖点秘密代理（本机 CLI）" | "## Cliora secret broker (local CLI)"
        ) && rest.len() >= 3
            && rest[0].trim().is_empty()
            && rest[1].starts_with(if line.starts_with("## Cliora") {
                "Installation: "
            } else {
                "安装标识: "
            })
            && rest[2].starts_with(if line.starts_with("## Cliora") {
                "Executable: "
            } else {
                "可执行文件: "
            })
        {
            output.push_str(lines[i]);
            i += 4;
            continue;
        }
        let fenced = line == "```" && rest.len() >= 2 && rest[1].trim_end() == "```";
        let command = if fenced { rest[0] } else { line };
        if let Some(replacement) = legacy_command(command) {
            output.push_str(&replacement);
            if fenced {
                i += 2;
            }
            output.push_str(&lines[i][lines[i].trim_end_matches(['\r', '\n']).len()..]);
        } else {
            output.push_str(lines[i]);
        }
        i += 1;
    }
    output.into()
}

pub fn normalize_prompt(body: &mut String) {
    if let std::borrow::Cow::Owned(portable) = prompt_body(body) {
        *body = portable;
    }
}
